import { Topic, EvidenceFilter, CategoryId, EraGroupId } from '../../types/archive';
import { ancientAndHistoryTopics } from './ancientAndHistory';
import { scienceAndSpaceTopics } from './scienceAndSpace';
import { governmentAndOperationsTopics } from './governmentAndOperations';
import { unexplainedPhenomenaTopics } from './unexplainedPhenomena';
import { internetAndMediaTopics } from './internetAndMedia';
import { socialAndSystemicTopics } from './socialAndSystemic';
import { secretSocietiesAndCultsTopics } from './secretSocietiesAndCults';
import { hiddenPowerAndDocumentsTopics } from './hiddenPowerAndDocuments';
import { uapAndAerospaceTopics } from './uapAndAerospace';
import { uapAndAerospaceHistoricalTopics } from './uapAndAerospaceHistorical';
import { uapAndAerospaceDeclassifiedTopics } from './uapAndAerospaceDeclassified';
import { secretSocietiesHistoricalTopics } from './secretSocietiesHistorical';
import { cultsAndMysteriesTopics } from './cultsAndMysteries';

const RAW_TOPICS: Topic[] = [
  ...ancientAndHistoryTopics,
  ...scienceAndSpaceTopics,
  ...governmentAndOperationsTopics,
  ...unexplainedPhenomenaTopics,
  ...internetAndMediaTopics,
  ...socialAndSystemicTopics,
  ...secretSocietiesAndCultsTopics,
  ...hiddenPowerAndDocumentsTopics,
  ...uapAndAerospaceTopics,
  ...uapAndAerospaceHistoricalTopics,
  ...uapAndAerospaceDeclassifiedTopics,
  ...secretSocietiesHistoricalTopics,
  ...cultsAndMysteriesTopics
];

// Deduplicate by ID and Slug, prioritizing later richer records
const seenIds = new Set<string>();
const seenSlugs = new Set<string>();
const deduplicatedTopics: Topic[] = [];

for (const topic of RAW_TOPICS) {
  const normId = topic.id.toUpperCase();
  const normSlug = topic.slug.toLowerCase();
  if (!seenIds.has(normId) && !seenSlugs.has(normSlug)) {
    seenIds.add(normId);
    seenSlugs.add(normSlug);
    deduplicatedTopics.push(topic);
  }
}

export const ALL_TOPICS: Topic[] = deduplicatedTopics;

export function getAllTopics(): Topic[] {
  return ALL_TOPICS;
}

export function getTopicBySlug(slug: string): Topic | undefined {
  return ALL_TOPICS.find((t) => t.slug.toLowerCase() === slug.toLowerCase());
}

export function getTopicById(id: string): Topic | undefined {
  return ALL_TOPICS.find((t) => t.id.toLowerCase() === id.toLowerCase());
}

export function getFeaturedTopics(): Topic[] {
  return ALL_TOPICS.filter((t) => t.featured);
}

export function getTopicsByCategory(categoryId: CategoryId): Topic[] {
  return ALL_TOPICS.filter((t) => t.category.toLowerCase() === categoryId.toLowerCase());
}

export function getTopicsByEra(era: EraGroupId): Topic[] {
  return ALL_TOPICS.filter((t) => t.eraGroup === era);
}

export function getRelatedTopics(topic: Topic, limit: number = 3): Topic[] {
  if (topic.relatedTopicIds && topic.relatedTopicIds.length > 0) {
    const related = topic.relatedTopicIds
      .map((id) => getTopicById(id))
      .filter((t): t is Topic => t !== undefined);
    if (related.length >= limit) return related.slice(0, limit);
  }

  // Fallback: match by category or shared tags
  const others = ALL_TOPICS.filter((t) => t.id !== topic.id);
  const byTagMatch = others.map((item) => {
    const sharedTags = item.tags.filter((tag) => topic.tags.includes(tag)).length;
    const sameCat = item.category === topic.category ? 2 : 0;
    return { item, score: sharedTags + sameCat };
  });

  byTagMatch.sort((a, b) => b.score - a.score);
  return byTagMatch.slice(0, limit).map((entry) => entry.item);
}

export function searchArchive(
  query: string,
  options?: {
    category?: CategoryId | 'All';
    status?: EvidenceFilter;
    era?: EraGroupId | 'All';
    hasPrimarySources?: boolean;
    tag?: string;
  }
): Topic[] {
  const q = query.trim().toLowerCase();

  return ALL_TOPICS.filter((topic) => {
    // Text search matching
    if (q) {
      const matchTitle = topic.title?.toLowerCase().includes(q) || false;
      const matchSubtitle = topic.subtitle ? topic.subtitle.toLowerCase().includes(q) : false;
      const matchSummary = topic.summary?.toLowerCase().includes(q) || false;
      const matchClaim = topic.claim ? topic.claim.toLowerCase().includes(q) : false;
      const matchTags = Array.isArray(topic.tags) ? topic.tags.some((tag) => tag.toLowerCase().includes(q)) : false;
      const matchFacts = Array.isArray(topic.establishedFacts) ? topic.establishedFacts.some((f) => f.toLowerCase().includes(q)) : false;
      const matchSources = Array.isArray(topic.sources) ? topic.sources.some((s) => s.title?.toLowerCase().includes(q) || (s.author && s.author.toLowerCase().includes(q))) : false;
      const matchId = topic.id?.toLowerCase().includes(q) || false;

      if (!matchTitle && !matchSubtitle && !matchSummary && !matchClaim && !matchTags && !matchFacts && !matchSources && !matchId) {
        return false;
      }
    }

    // Category filter
    if (options?.category && options.category !== 'All') {
      if (topic.category.toLowerCase() !== options.category.toLowerCase()) {
        return false;
      }
    }

    // Status filter
    if (options?.status && options.status !== 'ALL') {
      if (topic.status !== options.status) {
        return false;
      }
    }

    // Era filter
    if (options?.era && options.era !== 'All') {
      if (topic.eraGroup !== options.era) {
        return false;
      }
    }

    // Primary sources filter
    if (options?.hasPrimarySources) {
      const hasPrimary = topic.sources.some((s) => s.type === 'PRIMARY' || s.type === 'ARCHIVAL' || s.type === 'GOVERNMENT');
      if (!hasPrimary) return false;
    }

    // Tag filter
    if (options?.tag) {
      if (!topic.tags.includes(options.tag)) return false;
    }

    return true;
  });
}
